const FORMS40=[["talo","talon","taloa","taloon","talot","taloja","house","घर"],["auto","auton","autoa","autoon","autot","autoja","car","गाडी"],["kirja","kirjan","kirjaa","kirjaan","kirjat","kirjoja","book","किताब"],["koulu","koulun","koulua","kouluun","koulut","kouluja","school","विद्यालय"],["kauppa","kaupan","kauppaa","kauppaan","kaupat","kauppoja","shop","पसल"],["pöytä","pöydän","pöytää","pöytään","pöydät","pöytiä","table","टेबल"],["katu","kadun","katua","katuun","kadut","katuja","street","सडक"],["päivä","päivän","päivää","päivään","päivät","päiviä","day","दिन"],["koira","koiran","koiraa","koiraan","koirat","koiria","dog","कुकुर"],["kissa","kissan","kissaa","kissaan","kissat","kissoja","cat","बिरालो"],["omena","omenan","omenaa","omenaan","omenat","omenoita","apple","स्याउ"],["kala","kalan","kalaa","kalaan","kalat","kaloja","fish","माछा"],["leipä","leivän","leipää","leipään","leivät","leipiä","bread","रोटी"],["kahvi","kahvin","kahvia","kahviin","kahvit","kahveja","coffee","कफी"],["bussi","bussin","bussia","bussiin","bussit","busseja","bus","बस"],["pankki","pankin","pankkia","pankkiin","pankit","pankkeja","bank","बैंक"],["kaupunki","kaupungin","kaupunkia","kaupunkiin","kaupungit","kaupunkeja","city","शहर"],["tyttö","tytön","tyttöä","tyttöön","tytöt","tyttöjä","girl","केटी"],["poika","pojan","poikaa","poikaan","pojat","poikia","boy, son","केटा"],["äiti","äidin","äitiä","äitiin","äidit","äitejä","mother","आमा"],["ystävä","ystävän","ystävää","ystävään","ystävät","ystäviä","friend","साथी"],["kenkä","kengän","kenkää","kenkään","kengät","kenkiä","shoe","जुत्ता"],["huone","huoneen","huonetta","huoneeseen","huoneet","huoneita","room","कोठा"],["perhe","perheen","perhettä","perheeseen","perheet","perheitä","family","परिवार"],["kirje","kirjeen","kirjettä","kirjeeseen","kirjeet","kirjeitä","letter","चिठी"],["maa","maan","maata","maahan","maat","maita","country, land","देश"],["tee","teen","teetä","teehen","teet","teitä","tea","चिया"],["työ","työn","työtä","työhön","työt","töitä","work","काम"],["yö","yön","yötä","yöhön","yöt","öitä","night","रात"],["vesi","veden","vettä","veteen","vedet","vesiä","water","पानी"],["käsi","käden","kättä","käteen","kädet","käsiä","hand","हात"],["lapsi","lapsen","lasta","lapseen","lapset","lapsia","child","बच्चा"],["vuosi","vuoden","vuotta","vuoteen","vuodet","vuosia","year","वर्ष"],["uusi","uuden","uutta","uuteen","uudet","uusia","new","नयाँ"],["nimi","nimen","nimeä","nimeen","nimet","nimiä","name","नाम"],["järvi","järven","järveä","järveen","järvet","järviä","lake","ताल"],["kieli","kielen","kieltä","kieleen","kielet","kieliä","language","भाषा"],["nainen","naisen","naista","naiseen","naiset","naisia","woman","महिला"],["ihminen","ihmisen","ihmistä","ihmiseen","ihmiset","ihmisiä","person","मानिस"],["puhelin","puhelimen","puhelinta","puhelimeen","puhelimet","puhelimia","phone","फोन"],["avain","avaimen","avainta","avaimeen","avaimet","avaimia","key","साँचो"],["kysymys","kysymyksen","kysymystä","kysymykseen","kysymykset","kysymyksiä","question","प्रश्न"],["mies","miehen","miestä","mieheen","miehet","miehiä","man","पुरुष"],["Suomi","Suomen","Suomea","Suomeen","","","Finland","फिनल्यान्ड"],["Helsinki","Helsingin","Helsinkiä","Helsinkiin","","","Helsinki","हेल्सिंकी"]];
